public applyOptions(options?: AnimOptions): void {
    if (!options) return;

    const oldDuration = this.duration;
    super.applyOptions(options);

    if (oldDuration > 0 && this.duration !== oldDuration) {
        const scale = this.duration / oldDuration;
        for (const animation of this.animations) {
            animation.applyOptions({
                rate_func: this.rate_func,
                fps: options.fps ?? this.fps,
                interval: options.interval ?? this.interval,
                duration: animation.duration * scale,
                delay: animation.delay * scale,
            });
        }
    }
}

public update(dt: number): boolean {
    this.elapsed += dt;
    this.applyProgress(Math.min(1, this.elapsed / this.duration));

    if (this.elapsed < this.duration) return false;

    this.complete();
    return true;
}

