import { Sequential, Concurrent, StateAnimation, Rate } from "retiam";

// Phase 1: Parallel reveal of background card and icon
const phase1 = new Concurrent([
    new StateAnimation(card, cardVisibleState, { duration: 500 }),
    new StateAnimation(icon, iconVisibleState, { duration: 500 }),
]);

// Phase 2: Parallel focus pulse and color shift
const phase2 = new Concurrent([
    new StateAnimation(card, cardHighlightState, { duration: 300, rate_func: Rate.rushInto() }),
    new StateAnimation(icon, iconTintState, { duration: 300 }),
]);

// Phase 3: Settle back
const phase3 = new StateAnimation(card, cardRestingState, { duration: 400, rate_func: Rate.easeOutElastic() });

// Execute all 3 phases sequentially as one animation
const cardPresentation = new Sequential([phase1, phase2, phase3]);
await scene.play(cardPresentation);

import { Entity, Sequential, Concurrent, StateAnimation, Vec3, Rate } from "retiam";
import { PopHighlightOptions } from "../core/types";

export class PopHighlight extends Sequential {
    constructor(target: Entity | Entity[], options: PopHighlightOptions = {}) {
        const duration = options.duration ?? 500;
        const scaleFactor = options.scaleFactor ?? 1.2;
        const targets = Array.isArray(target) ? target : [target];

        const popAnims: StateAnimation[] = [];
        const settleAnims: StateAnimation[] = [];

        const popDuration = duration * 0.4;
        const settleDuration = duration * 0.6;

        for (const ent of targets) {
            const originalState = ent.state.copy();
            const poppedState = originalState.copy();

            const cur = ent.transform.scaling;
            poppedState.transform.setScale(
                new Vec3(cur.x * scaleFactor, cur.y * scaleFactor, cur.z)
            );

            // Phase 1: Quick punch out
            popAnims.push(
                new StateAnimation(ent, poppedState, {
                    duration: popDuration,
                    rate_func: Rate.easeOutQuad(),
                })
            );

            // Phase 2: Elastic settle back
            settleAnims.push(
                new StateAnimation(ent, originalState, {
                    duration: settleDuration,
                    rate_func: Rate.easeOutElastic(),
                })
            );
        }

        // Pass child groups to Sequential super constructor
        super(
            [new Concurrent(popAnims), new Concurrent(settleAnims)],
            options
        );

        this.LABEL = "PopHighlight";
        this.entity = target;
    }
}
